function CoffeeCard({ name, title, price = 3, onOrder, soldOut = false }: CoffeeProps) {
  return (
    <article aria-label={name} title={title}>
      <h2>{label(name)}</h2>
      <p>EUR {price.toFixed(2)}</p>
      {onOrder && <button type="button" disabled={soldOut} onClick={() => onOrder(name)}>Add {name}</button>}
    </article>
  )
}

(order: Order) => {
  function hasDrinks() { return order.items.length > 0; }
  if (hasDrinks()) order.status = "ready";
  return order;
}

function* expandDrinks(order: Order) {
  function drinkLabel(name: string, index: number) { return `${name} #${index + 1}`; }
  for (const item of order.items) {
    for (let index = 0; index < item.quantity; index++) yield drinkLabel(item.name, index);
  }
}

